export function analyzeSession(project){if(!project||!Number.isFinite(project.bpm)||project.bpm<=0||!Array.isArray(project.tracks))throw Error('Session invalide');const tracks=project.tracks.map(t=>{let notes=0,hits=0,clips=0,velocity=0;const pitches=new Set();for(const c of t.clips||[]){if(c.muted)continue;clips++;for(const n of c.notes||[]){if(n.muted||!Number.isInteger(n.midi)||n.midi<0||n.midi>127)continue;notes++;pitches.add(n.midi%12);if(Number.isFinite(n.velocity))velocity+=n.velocity;}for(const row of Object.values(c.pattern||{}))if(Array.isArray(row))hits+=row.filter(x=>Number.isFinite(x)&&x>0).length;}return {id:t.id??null,name:t.name??'',type:t.type??'unknown',muted:!!t.mute,clips,notes,hits,pitchClasses:[...pitches].sort((a,b)=>a-b),meanVelocity:notes?velocity/notes:null};});return {schema:'warlike.ar.report.v1',bpm:project.bpm,tracks,totalNotes:tracks.reduce((s,t)=>s+(t.muted?0:t.notes),0),totalDrumHits:tracks.reduce((s,t)=>s+(t.muted?0:t.hits),0),limitations:['MIDI et patterns uniquement; aucune analyse du signal audio ni prédiction commerciale.']};}